INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'patients', 'subject_number', 'NOT_NULL', 'subject_number IS NOT NULL', 'Subject number must not be null');
INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'patients', 'enrollment_date', 'NOT_NULL', 'enrollment_date IS NOT NULL', 'Enrollment date must not be null for active subjects');
INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'demographics', 'sex', 'NOT_NULL', 'sex IS NOT NULL', 'Sex must not be null');
INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'lab_results', 'result_value', 'NOT_NULL', 'result_value IS NOT NULL', 'Result value must not be null');
INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'visits', 'actual_date', 'NOT_NULL', 'actual_date IS NOT NULL', 'Visit actual date must not be null');
INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'lab_results', 'result_value', 'FORMAT', 'result_value ~ ''^[0-9]+\.?[0-9]*$''', 'Result value must be numeric');
INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'vital_signs', 'systolic_bp', 'RANGE', 'systolic_bp BETWEEN 50 AND 300', 'Systolic BP out of range');
INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'adverse_events', 'onset_date', 'NOT_NULL', 'onset_date IS NOT NULL', 'AE onset date must not be null');
INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'randomization', 'arm_id', 'NOT_NULL', 'arm_id IS NOT NULL', 'Randomization must have an arm');
INSERT INTO az_clinical.validation_rules (study_id, table_name, column_name, rule_type, rule_expression, error_message) VALUES (1, 'crf_data', 'data', 'NOT_NULL', 'data IS NOT NULL', 'CRF data must not be null');
